 if(!valid.length)return el('p','meta','No numerical points supplied.');
 let times=points.map(p=>typeof p.time==='string'&&/(Z|[+-]\d\d:\d\d)$/i.test(p.time)?Date.parse(p.time):NaN),timed=times.every(Number.isFinite)&&Math.max(...times)>Math.min(...times),tmin=timed?Math.min(...times):0,tmax=timed?Math.max(...times):0;
 let box=el('div'),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 600 140');svg.setAttribute('class','chart');svg.setAttribute('role','img');
 let min=Math.min(...valid.map(x=>x.p.value)),max=Math.max(...valid.map(x=>x.p.value)),range=max-min||1;
 svg.setAttribute('aria-label',`${s.id}: ${valid.length} individual points, range ${fmt(min)} to ${fmt(max)} ${txt(unit)}. ${timed?'Positioned by timestamp.':'Ordered by sample index; timestamps unavailable.'} Points are not connected.`);
 if(s.id==='daily_returns'){let lo=Math.min(0,min),hi=Math.max(0,max),span=hi-lo||1,zero=125-(0-lo)/span*105;valid.forEach(({p,i})=>{let rect=document.createElementNS(svg.namespaceURI,'rect'),y=125-(p.value-lo)/span*105;rect.setAttribute('x',String(15+i*570/points.length));rect.setAttribute('y',String(Math.min(y,zero)));rect.setAttribute('width',String(Math.max(2,500/points.length)));rect.setAttribute('height',String(Math.max(1,Math.abs(y-zero))));rect.setAttribute('fill',p.value<0?'#b87350':'#2d7b67');svg.append(rect)})}
 else valid.forEach(({p,i})=>{let dot=document.createElementNS(svg.namespaceURI,'circle');dot.setAttribute('cx',String(timed?15+(times[i]-tmin)*570/(tmax-tmin):points.length>1?15+i*570/(points.length-1):300));dot.setAttribute('cy',String(125-(p.value-min)/range*105));dot.setAttribute('r','3');dot.setAttribute('fill','#2d7b67');svg.append(dot)});
